// Validación tolerante para cuerpos recibidos desde Webhook de n8n.
// Acepta body JSON como objeto, body como texto JSON y facturaId en raíz.
const entrada = $json ?? {};
let body = entrada.body ?? entrada;

if (typeof body === 'string') {
  try {
    body = JSON.parse(body);
  } catch (e) {
    return [{ json: {
      valido: false,
      httpStatus: 400,
      error: 'JSON_INVALIDO',
      mensaje: 'El body debe ser JSON válido. Usa Body > raw > JSON en Postman.'
    }}];
  }
}

// Algunos clientes/nodos pueden envolver los datos en otra propiedad.
if (body && typeof body === 'object' && body.data && typeof body.data === 'object' && body.facturaId === undefined) {
  body = body.data;
}

let facturaId = body?.facturaId ?? entrada.facturaId;
if (facturaId !== undefined && facturaId !== null) {
  facturaId = String(facturaId).trim();
}

if (!facturaId) {
  return [{ json: {
    valido: false,
    httpStatus: 400,
    error: 'FACTURA_ID_REQUERIDO',
    mensaje: 'Falta facturaId. Envía {"facturaId":"F001"} en Body > raw > JSON.',
    recibido: entrada
  }}];
}

return [{ json: { valido: true, facturaId } }];

// La misma regla de negocio se puede probar fuera de n8n con clases equivalentes en JavaScript.
class Factura {
  constructor(datos) {
    this.id = datos.id;
    this.fechaEmision = datos.fechaEmision;
    this.diasHabilesCredito = Number(datos.diasHabilesCredito ?? 15);
    this.estado = datos.estado ?? 'pendiente';
  }

  validar() {
    if (!this.id) throw new Error('La factura no contiene identificador.');
    if (!this.fechaEmision || !/^\d{4}-\d{2}-\d{2}$/.test(this.fechaEmision)) {
      throw new Error('La fechaEmision debe tener formato YYYY-MM-DD.');
    }
    if (!Number.isInteger(this.diasHabilesCredito) || this.diasHabilesCredito < 1) {
      throw new Error('diasHabilesCredito debe ser un entero positivo.');
    }
  }

  clasificar(fechaVencimiento, hoy) {
    return hoy > fechaVencimiento ? 'vencida' : 'pendiente';
  }
}

class CalendarioLaboral {
  constructor(feriados) {
    this.feriados = new Set((feriados || []).map(f => f.date).filter(Boolean));
  }

  esDiaHabil(fecha) {
    const dia = fecha.getUTCDay();
    const iso = fecha.toISOString().slice(0, 10);
    return dia !== 0 && dia !== 6 && !this.feriados.has(iso);
  }

  sumarDiasHabiles(fechaISO, cantidad) {
    const fecha = new Date(`${fechaISO}T12:00:00.000Z`);
    let sumados = 0;
    while (sumados < cantidad) {
      fecha.setUTCDate(fecha.getUTCDate() + 1);
      if (this.esDiaHabil(fecha)) sumados++;
    }
    return fecha.toISOString().slice(0, 10);
  }
}

const facturaData = $('Obtener factura').first().json;
const rawFeriados = $input.all().map(item => item.json);
const feriados = rawFeriados.flatMap(item => Array.isArray(item) ? item : (item && item.date ? [item] : []));
const factura = new Factura(facturaData);
factura.validar();

const calendario = new CalendarioLaboral(feriados);
const fechaVencimiento = calendario.sumarDiasHabiles(
  factura.fechaEmision,
  factura.diasHabilesCredito
);
const hoy = new Date().toISOString().slice(0, 10);
const estado = factura.clasificar(fechaVencimiento, hoy);

const facturaActualizada = {
  ...facturaData,
  fechaVencimiento,
  estado,
  diasHabilesCredito: factura.diasHabilesCredito,
  ultimaRevision: new Date().toISOString(),
  reglaAplicada: 'Vencimiento calculado en días hábiles; se excluyen sábados, domingos y feriados de Costa Rica.'
};

return [{ json: {
  facturaId: factura.id,
  fechaVencimiento,
  estado,
  facturaActualizada,
  mensaje: estado === 'vencida'
    ? `La factura ${factura.id} está vencida.`
    : `La factura ${factura.id} sigue pendiente; todavía no vence.`
}}];
